def min_vertex_cover(edges):
    # edges is a list of (u, v)
    # We want to find a minimum set of vertices such that every edge is covered.
    # The vertices are the unique elements in the edges.
    vertices = list(set(v for edge in edges for v in edge))

    def solve(edges_left):
        if not edges_left:
            return 0

        # Pick an edge (u, v)
        u, v = edges_left[0]

        # Case 1: u is in the vertex cover
        # Remove all edges covered by u
        edges_u = [e for e in edges_left if u not in e]
        res1 = 1 + solve(edges_u)

        # Case 2: v is in the vertex cover
        # Remove all edges covered by v
        edges_v = [e for e in edges_left if v not in e]
        res2 = 1 + solve(edges_v)

        return min(res1, res2)

    # Use memoization for the recursive solve
    memo = {}
    def solve_memo(edges_left):
        edges_left = tuple(sorted(edges_left))
        if edges_left in memo:
            return memo[edges_left]

        if not edges_left:
            return 0

        u, v = edges_left[0]

        # Case 1: u is in the vertex cover
        edges_u = tuple(sorted([e for e in edges_left if u not in e]))
        res1 = 1 + solve_memo(edges_u)

        # Case 2: v is in the vertex cover
        edges_v = tuple(sorted([e for e in edges_left if v not in e]))
        res2 = 1 + solve_memo(edges_v)

        memo[edges_left] = min(res1, res2)
        return memo[edges_left]

    return solve_memo(tuple(sorted(edges)))

