    # But we need to make sure they are still a set of dominoes.
    # The problem is that the remaining cells might not be tileable.
    # And they might not form a connected region.
    # We can use a recursive function with memoization.

    memo = {}
    remaining_cells = sorted(list(cells))
    cell_to_idx = {cell: i for i, cell in enumerate(remaining_cells)}

    def solve(mask):
        if mask == (1 << len(remaining_cells)) - 1:
            return 1
        if mask in memo:
            return memo[mask]

        i = 0
        while (mask >> i) & 1:
            i += 1

        r, c = remaining_cells[i]
