def is_flip(tiling, r, c):
    # tiling is a list of dominoes, each domino is ((r1, c1), (r2, c2))
    # A 2x2 area starting at (r, c) is a flip if it's covered by exactly two dominoes.
    # The cells are (r,c), (r,c+1), (r+1,c), (r+1,c+1)
    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
    dominoes_in_area = []
    for d in tiling:
        overlap = 0
        for cell in cells:
            if cell in d:
                overlap += 1
        if overlap > 0:
            dominoes_in_area.append(d)

    if len(dominoes_in_area) == 2:
        # Check if they are two horizontal or two vertical
        d1 = dominoes_in_area[0]
        d2 = dominoes_in_area[1]
        # Check horizontal: d1 = {(r,c), (r,c+1)}, d2 = {(r+1,c), (r+1,c+1)}
        # or d1 = {(r+1,c), (r+1,c+1)}, d2 = {(r,c), (r,c+1)}
        h1 = {(r, c), (r, c+1)}
        h2 = {(r+1, c), (r+1, c+1)}
        if (d1 == h1 and d2 == h2) or (d1 == h2 and d2 == h1):
            return True

        v1 = {(r, c), (r+1, c)}
        v2 = {(r, c+1), (r+1, c+1)}
        if (d1 == v1 and d2 == v2) or (d1 == v2 and d2 == v1):
            return True
    return False

