def generate_tilings(n):
    # Simple recursive tiling generation
    def solve(board):
        if not board:
            return [[]]

        # Find first empty cell
        r, c = -1, -1
        for i in range(n):
            for j in range(n):
                if (i, j) not in board:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:
            return [[]]

        res = []
        # Try horizontal
        if c + 1 < n and (r, c+1) not in board:
            board.add((r, c))
            board.add((r, c+1))
            sub_tilings = solve(board)
            for st in sub_tilings:
                res.append([((r, c), (r, c+1))] + st)
            board.remove((r, c))
            board.remove((r, c+1))

        # Try vertical
        if r + 1 < n and (r+1, c) not in board:
            board.add((r, c))
            board.add((r+1, c))
            sub_tilings = solve(board)
            for st in sub_tilings:
                res.append([((r, c), (r+1, c))] + st)
            board.remove((r, c))
            board.remove((r+1, c))
        return res

    board = set()
    return solve(board)

